# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('tremble','/ˈtrembəl/','发抖；颤动','身体或某个部位出现小幅、快速、难以稳住的抖动。','拉丁 tremere 颤抖 → tremulus 颤抖的 → 中世纪拉丁 tremulare → 古法语 trembler → 英语 tremble。',[['拉丁 tremere → tremulus → tremulare','颤抖 → 颤抖的 → 颤动'],['古法语 trembler → 中古英语 tremblen → tremble','发抖、因恐惧或情绪而颤动']],'冷、害怕、激动都可能让人 tremble，声音也可以 tremble。说 tremble with fear 是害怕得发抖，不必真的全身大幅摇晃。比喻 tremble at the thought of… 则是想到某事就害怕。','tremble with fear；tremble with excitement；a voice trembles；tremble at the thought。','shake 范围更广，可以主动摇一个东西；tremble 通常是不由自主的小幅颤动，常不及物。',('Her hands trembled as she opened the letter.','她打开信时，双手在发抖。'),('His voice trembled with excitement.','他的声音因激动而颤抖。'),sources=['https://www.etymonline.com/word/tremble','https://en.wiktionary.org/wiki/tremble#English']),
E('trembling','/ˈtremblɪŋ/','颤抖的；颤动；正在发抖','把镜头停在抖动正在发生的一刻。','tremble 去掉词尾不发音的 e，加 -ing。它可作现在分词、形容词，也能用作表示颤抖的名词。',[['英语 tremble','发抖、颤动'],['英语 trembling','正在颤抖；颤抖的状态或动作']],'trembling hands 是正在发抖的双手；She was trembling 用它构成进行时；the trembling in his voice 则把声音的颤动当作名词说。形式相同，句子里的工作不同。','trembling hands；a trembling voice；stop trembling；the trembling of leaves。','trembling 可以直接、具体地说正在抖；tremulous 更像书面描写，常带脆弱、紧张或不稳定的感觉。',('She signed the form with trembling hands.','她双手发抖地签了表格。'),('He tried to hide the trembling in his voice.','他试图掩饰声音中的颤抖。'),sources=['https://en.wiktionary.org/wiki/trembling#English']),
E('tremor','英 /ˈtremə/；美 /ˈtremər/','震颤；轻微震动；声音的颤抖','抓住那一阵抖动本身：手在抖，地面在抖，声音也可能轻轻发颤。','来自古法语 tremor、拉丁 tremor，源于 tremere 颤抖。早期英语有因恐惧而发颤的意思，后来更一般的震颤义可能又受拉丁语借入影响。',[['拉丁 tremere → tremor','颤抖 → 颤抖这一现象'],['古法语 tremor → 英语 tremor；后有拉丁影响','恐惧的颤抖 → 身体、地面等的震动']],'an earth tremor 是地面的轻微震动，a tremor in someone’s voice 是声音里的颤抖。医学里的 tremor 常指身体部位不自主而有节律的抖动；这个词本身不是某一种病的名称。','an earth tremor；a slight tremor；a tremor in the voice；hand tremor。','tremble 常用作动词，tremor 是名词。earthquake 泛指地震，earth tremor 常突出较轻的震动。',('A slight earth tremor shook the windows.','一阵轻微的地面震动使窗户晃动。'),('There was a tremor in her voice when she spoke.','她说话时声音里带着一丝颤抖。'),sources=['https://www.etymonline.com/word/tremor','https://medlineplus.gov/tremor.html']),
E('tremulous','/ˈtremjələs/','颤抖的；微颤的；紧张不安的','声音或动作稳不住，带着一点脆弱、迟疑或情绪。','借自拉丁 tremulus 颤抖的，来自 tremere 颤抖；英语以 -ous 形容词形式承接。它与 tremble 共享拉丁材料，不是把英语 tremble 随便换尾巴。',[['拉丁 tremere → tremulus','颤抖 → 颤抖的'],['英语 tremulous','微颤、不稳；常带情绪色彩']],'a tremulous voice 常让人听出害怕、激动或快哭出来的情绪；a tremulous smile 则是一个勉强维持、不太稳的微笑。这个词比 shaking 更有文学描写感。','a tremulous voice；a tremulous smile；a tremulous hand。','timid 是胆怯的性格或表现；tremulous 可以只是眼前这一刻的颤抖，并不证明这个人平时胆小。',('She answered in a tremulous voice.','她用微微发颤的声音回答。'),('He gave a tremulous smile before stepping onto the stage.','走上舞台前，他露出了一个略带不安的微笑。'),sources=['https://www.etymonline.com/word/tremulous','https://en.wiktionary.org/wiki/tremulous#English']),
E('tremendous','/trəˈmendəs/','极大的；惊人的；极好的','强大得让人震动，后来连特别好的事情也能这样夸。','来自拉丁 tremendus，应当令人颤抖的、可怕的，是 tremere 的动形词。英语早期偏可怕，后来通过夸张语气发展出极大、极好的意思。',[['拉丁 tremere → tremendus','颤抖 → 令人发抖、可畏的'],['早期英语 tremendous','可怕、令人敬畏的'],['现代常用 tremendous','极大、惊人；也可表示极好']],'tremendous pressure 是巨大的压力，不是会发抖的压力；a tremendous performance 是极精彩的表演。评价好坏由名词和语境决定：tremendous damage 仍是很大的损失。','tremendous effort；tremendous pressure；a tremendous success；tremendous damage。','tremulous 是在发抖的；tremendous 现代常说程度极大或非常好。两者同源但不能按一个中文意思换用。',('The project required a tremendous amount of work.','这个项目需要投入大量工作。'),('The team gave a tremendous performance in the final.','这支队伍在决赛中的表现极为出色。'),sources=['https://www.etymonline.com/word/tremendous','https://en.wiktionary.org/wiki/tremendous#English']),
E('tremendously','/trəˈmendəsli/','极其；非常；大大地','把程度旋钮一下拧到很高。','tremendous + -ly，现代副词通常承接极大、极好的意思，不需要再理解成令人发抖地。',[['英语 tremendous','极大的、极好的'],['英语 tremendously','程度很高；极其、非常']],'tremendously helpful 是帮助特别大，improve tremendously 是进步很大。它可以修饰形容词，也可以直接修饰动词。语气比 very 更强、更有情绪。','tremendously helpful；tremendously exciting；improve tremendously；enjoy something tremendously。','tremendous 放在名词前，如 tremendous progress；tremendously 修饰动词或形容词，如 improve tremendously。',('Your advice was tremendously helpful.','你的建议帮了大忙。'),('She enjoyed the concert tremendously.','她非常喜欢这场音乐会。'),sources=['https://www.oxfordlearnersdictionaries.com/us/definition/english/tremendously','https://en.wiktionary.org/wiki/tremendously#English'])]
ROOT=dict(id='C1542',meaning='颤抖；使人震动',core='TREM = TREMBLE',image='一边是手和声音在发抖；另一边是东西强大到令人震动，于是 tremendous 走向巨大、极好。',intro='拉丁 tremere 表示颤抖。tremor 说颤抖现象，tremulous 形容微颤，tremendous 的历史则经过令人害怕和敬畏，才走到今天的程度强调。',forms='tremere → tremulus → 法语 trembler → tremble；tremere → tremor；tremulus → tremulous；tremere → tremendus → tremendous。这些是不同分支，不能写成所有词都由英语 tremble 派生。',branches=[['抖动动作与状态','tremble；trembling；tremor；tremulous'],['令人震动的程度','tremendous；tremendously']],contrasts='tremulous voice 是微颤的声音，tremendous voice 可以是在夸声音很有力量、很出色。后者早期的可怕义不代表现代夸奖是在骂人。',practice='She spoke in a tremulous voice, but the audience gave her tremendous support.\n\n她说话时声音微颤，但观众给了她极大的支持。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_trem',[ROOT]),('words_trem',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
